const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isUuid(value: string): boolean {
  return UUID_RE.test(value);
}

// Matches fn-post-confirmation's fallback pattern (user_<first 8 chars of the
// Cognito sub>) — fired for every real signup so far, since Cognito's Hosted
// UI never surfaces the optional preferred_username field on its signup
// form. Used to gate the one-time "choose your username" prompt: only
// offered while the username still looks auto-generated, matching the
// "immutable after signup" rule once a real one has been chosen.
const AUTO_USERNAME_RE = /^user_[0-9a-f]{8}$/;

export function isAutoGeneratedUsername(username: string): boolean {
  return AUTO_USERNAME_RE.test(username);
}

const USERNAME_RE = /^[a-z0-9_]{3,20}$/;

export function isValidUsername(value: unknown): value is string {
  return typeof value === "string" && USERNAME_RE.test(value);
}

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

// Format check + real-calendar-date check + not-in-the-future, all before this
// ever reaches Postgres — an uncaught cast error on a malformed date string
// would otherwise surface as a raw 500 instead of a clean 400.
export function isValidNonFutureDate(value: unknown): value is string {
  if (typeof value !== "string" || !DATE_RE.test(value)) {
    return false;
  }
  const parsed = new Date(`${value}T00:00:00Z`);
  if (Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== value) {
    return false;
  }
  const today = new Date().toISOString().slice(0, 10);
  return value <= today;
}
